"""Builder levers for built-in tools in ``orchestrator.tool_constraints``."""

from __future__ import annotations

import copy
from collections.abc import Mapping
from typing import Annotated, Any

import pydantic
from pydantic import (
    AfterValidator,
    BaseModel,
    BeforeValidator,
    ConfigDict,
    Field,
    field_validator,
)
from pydantic.json_schema import SkipJsonSchema

from rasa.mantle.llm.tool_schemas import (
    TOOL_ACTIVATE,
    TOOL_CANCEL,
    TOOL_CANNOT_HELP,
    TOOL_COMPLETE,
    TOOL_CORRECT,
    TOOL_SEARCH_KNOWLEDGE,
    TOOL_SET_FIELDS,
)
from rasa.mantle.skills.conditions import (
    REQUIRES_CONFIRMATION_FIELD,
    RequiresConfirmation,
)
from rasa.mantle.skills.frontmatter import RequiresConfirmationDocument

_DISABLEABLE_TOOLS: frozenset[str] = frozenset(
    {
        TOOL_CANCEL,
        TOOL_COMPLETE,
        TOOL_SEARCH_KNOWLEDGE,
        TOOL_CANNOT_HELP,
    }
)
_CONFIGURABLE_TOOLS: frozenset[str] = _DISABLEABLE_TOOLS | frozenset(
    {TOOL_ACTIVATE, TOOL_CORRECT, TOOL_SET_FIELDS}
)
_CONFIRMABLE_TOOLS: frozenset[str] = frozenset({TOOL_CANCEL})


class BuiltinToolConstraint(BaseModel):
    """``enabled``, ``invoke_when`` and ``requires_confirmation`` for one built-in.

    ``enabled`` defaults to on. ``invoke_when`` is optional builder text for
    when the model should call the tool. ``requires_confirmation`` is accepted
    on ``cancel`` only; ``enabled: false`` and an omitted gate are stored
    as no confirmation, and a bare ``requires_confirmation:`` fails. Any other
    key is rejected.
    """

    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)

    enabled: bool = True
    invoke_when: str | None = None
    requires_confirmation: RequiresConfirmation | SkipJsonSchema[None] = None

    @field_validator("invoke_when")
    @classmethod
    def _reject_blank_invoke_when(cls, value: str | None) -> str | None:
        """Reject empty or whitespace-only when-to-call text."""
        if value is None:
            return None
        if not value.strip():
            raise ValueError(
                "invoke_when must be a non-empty string; omit the key to keep "
                "the default wording"
            )
        return value

    @field_validator("requires_confirmation", mode="before")
    @classmethod
    def _parse_requires_confirmation(cls, value: Any) -> RequiresConfirmation | None:
        """Store an enabled gate and drop a disabled one.

        A present null or a non-mapping fails. Response names on a disabled
        gate are discarded. Nested keys are checked with the same strict
        document skill tools use, so a string ``enabled`` does not coerce.
        """
        if isinstance(value, RequiresConfirmation):
            return value if value.enabled else None
        if value is None or not isinstance(value, Mapping):
            raise ValueError("requires_confirmation must be a mapping")
        return _confirmation_from_mapping(value)


def _confirmation_from_mapping(
    value: Mapping[str, Any],
) -> RequiresConfirmation | None:
    """Parse a confirmation mapping, or return ``None`` when the gate is off."""
    try:
        document = RequiresConfirmationDocument.model_validate(dict(value))
    except pydantic.ValidationError as error:
        messages = "; ".join(
            issue["msg"] for issue in error.errors(include_input=False)
        )
        raise ValueError(messages) from error
    if not document.enabled:
        return None
    return RequiresConfirmation(
        enabled=True,
        utter_for_confirmation=document.utter_for_confirmation,
        utter_on_user_denial=document.utter_on_user_denial,
    )


def _reject_disallowed_requires_confirmation(raw: Any) -> Any:
    """Reject ``requires_confirmation`` on any built-in that cannot pause.

    Runs on the raw mapping, so a disabled gate on such a tool is still an
    error rather than being normalised away before the check.
    """
    if not isinstance(raw, Mapping):
        return raw
    for tool_name, entry in raw.items():
        if tool_name in _CONFIRMABLE_TOOLS:
            continue
        if isinstance(entry, BuiltinToolConstraint):
            has_confirmation = entry.requires_confirmation is not None
        else:
            has_confirmation = (
                isinstance(entry, Mapping) and REQUIRES_CONFIRMATION_FIELD in entry
            )
        if not has_confirmation:
            continue
        raise ValueError(
            f"tool_constraints.{tool_name}: requires_confirmation is not "
            f"allowed on '{tool_name}'"
        )
    return raw


def _reject_disallowed_builtin_tools(
    constraints: dict[str, BuiltinToolConstraint],
) -> dict[str, BuiltinToolConstraint]:
    """Reject unknown names and ``enabled: false`` on tools that stay on."""
    for tool_name, constraint in constraints.items():
        if tool_name not in _CONFIGURABLE_TOOLS:
            raise ValueError(
                f"tool_constraints.{tool_name}: tool '{tool_name}' is not "
                "configurable"
            )
        if not constraint.enabled and tool_name not in _DISABLEABLE_TOOLS:
            raise ValueError(
                f"tool_constraints.{tool_name}.enabled: tool '{tool_name}' "
                "cannot be turned off"
            )
    return constraints


def _tool_constraints_json_schema(schema: dict[str, Any]) -> None:
    """Allow ``requires_confirmation`` on ``cancel`` only.

    The runtime model is shared, so its schema still describes the field.
    Each other built-in forbids that property. Unknown tool names stay invalid.
    """
    names = sorted(_CONFIGURABLE_TOOLS)
    schema["propertyNames"] = {"enum": names}
    shared = copy.deepcopy(schema.pop("additionalProperties"))
    schema["additionalProperties"] = False
    schema["properties"] = {
        name: (
            shared
            if name in _CONFIRMABLE_TOOLS
            else {
                "allOf": [shared],
                "not": {"required": ["requires_confirmation"]},
            }
        )
        for name in names
    }


BuiltinToolConstraints = Annotated[
    dict[str, BuiltinToolConstraint],
    BeforeValidator(_reject_disallowed_requires_confirmation),
    AfterValidator(_reject_disallowed_builtin_tools),
    Field(json_schema_extra=_tool_constraints_json_schema),
]
"""Mapping of built-in tool name to that tool's levers. Default empty."""


def builtin_tool_enabled(
    constraints: Mapping[str, BuiltinToolConstraint],
    tool_name: str,
) -> bool:
    """Return whether *tool_name* is still offered.

    A missing entry stays on. Only ``enabled`` is read.
    """
    constraint = constraints.get(tool_name)
    if constraint is None:
        return True
    return constraint.enabled


def cancel_skill_confirmation(
    constraints: Mapping[str, BuiltinToolConstraint],
) -> RequiresConfirmation | None:
    """Return the ``cancel`` confirmation gate, or ``None`` for immediate cancel.

    A missing entry and a disabled gate both mean cancel runs without asking.
    """
    constraint = constraints.get(TOOL_CANCEL)
    if constraint is None:
        return None
    return constraint.requires_confirmation


def knowledge_search_offered(
    constraints: Mapping[str, BuiltinToolConstraint],
    references_index_packaged: bool,
) -> bool:
    """Return whether ``search_knowledge`` can be offered on this model.

    A packaged references index is required. Turning the tool off makes the
    turn behave as if no index were packaged: the tool is not offered, the
    prompt does not steer to it, and ``cannot_help`` is offered without a
    search having run. The index itself stays in the archive.
    """
    return references_index_packaged and builtin_tool_enabled(
        constraints, TOOL_SEARCH_KNOWLEDGE
    )
